  approvedCount: HANSOL_PLACEMENTS.length,
  additionalCount: 0,
  coreIds: MODEL_IDS,
  startBuildingId: MODEL_IDS[0],
  // camera picked by scripts/auto-school/build.mjs from the measured occlusion (azimuths in radians, elevations in degrees, src/camera.js angles)
  view: Object.freeze({ startFrame: HANSOL_START_FRAME, overviewAzimuth: HANSOL_OVERVIEW_AZIMUTH }),
  camera: HANSOL_CAMERA,
  models: Object.freeze({
    manifests: Object.freeze([
      Object.freeze({ url: asset('manifest.json'), expectedIds: MODEL_IDS }),
      Object.freeze({ url: asset('environment.json'), expectedIds: HANSOL_ENV_IDS }),
    ]),
    proceduralIds: Object.freeze([]),
    createProceduralSource: () => { throw new Error('No procedural buildings in this campus'); },
    enhanceFacade: () => ({ stats: {}, dispose() {} }),
  }),
  terrain: Object.freeze({ heightGrids: HANSOL_HEIGHT_GRIDS, buildingBase: HANSOL_BUILDING_BASE, source: HANSOL_PROVENANCE.terrain }),
  environment: Object.freeze({ provenance: HANSOL_PROVENANCE, sourceNote: 'OSM ground surfaces and surroundings (© OpenStreetMap contributors, ODbL); heights, floors and planting estimated automatically' }),
  ground: Object.freeze({
    baked: Object.freeze({ envIds: HANSOL_ENV_IDS, castShadow: Object.freeze([]),
      fade: Object.freeze({ centre_m: Object.freeze([...FADE.centreEN]), near_m: FADE.r0_m, far_m: FADE.r1_m, linear: FADE.linearShare, colour: HAZE }), playMargin_m: 30,
      source: 'scripts/auto-school/build.mjs baked ground' }),
  }),
  protected: Object.freeze({ models: HANSOL_PROTECTED }),
  hazardTape: Object.freeze({ footprints: HANSOL_FOOTPRINTS }),
